from collections import deque
from typing import List, Deque, NamedTuple, Set, Tuple

class Cell(NamedTuple):
    row: int
    col: int

def solve(grid: List[str], start: Cell, goal: Cell) -> List[Cell]:
    if start == goal and grid[start.row][start.col] == '.':
        return [start]
    if grid[start.row][start.col] == '#' or grid[goal.row][goal.col] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = set()
    queue: Deque[Tuple[Cell, List[Cell]]] = deque([(start, [start])])

    while queue:
        current, path = queue.popleft()
        if current == goal:
            return path
        for dr, dc in directions:
            next_row, next_col = current.row + dr, current.col + dc
            if 0 <= next_row < rows and 0 <= next_col < cols and grid[next_row][next_col] == '.' and (next_row, next_col) not in visited:
                visited.add((next_row, next_col))
                queue.append((Cell(next_row, next_col), path + [Cell(next_row, next_col)]))

    return []
