from collections import deque

def solve(grid, start, goal):
    ROWS, COLS = len(grid), len(grid[0])
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    queue = deque([start])
    visited = {start: None}

    while queue:
        curr = queue.popleft()
        for dr, dc in directions:
            r, c = curr[0] + dr, curr[1] + dc
            if 0 <= r < ROWS and 0 <= c < COLS and grid[r][c] == '.' and (r, c) not in visited:
                visited[(r, c)] = curr
                queue.append((r, c))
                if (r, c) == goal:
                    path = []
                    while (r, c) != start:
                        path.append((r, c))
                        r, c = visited[(r, c)]
                    path.append(start)
                    return path[::-1]
    return []
