def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    queue = deque([start])
    visited = set([start])

    while queue:
        row, col = queue.popleft()
        if (row, col) == goal:
            return [(row, col)] + get_path(visited, start)

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                queue.append((nr, nc))
                visited.add((nr, nc))

    return []

def get_path(visited, start):
    path = []
    while visited:
        current = visited.pop()
        path.append(current)
        if current == start:
            return path
    return []
