from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(pos):
        row, col = pos
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def bfs(start, goal):
        queue = deque([start])
        visited = set([start])
        path = {start: None}

        while queue:
            current = queue.popleft()
            if current == goal:
                break

            for dr, dc in directions:
                neighbor = (current[0] + dr, current[1] + dc)
                if is_valid(neighbor) and neighbor not in visited:
                    visited.add(neighbor)
                    path[neighbor] = current
                    queue.append(neighbor)

        if goal not in path:
            return []

        result = []
        while goal:
            result.append(goal)
            goal = path.get(goal, None)
        return result[::-1]

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    return bfs(start, goal)
