def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    def dijkstra(start):
        dist = [float('inf')] * n
        dist[start] = 0
        min_heap = [(0, start)]
        while min_heap:
            d, cur = heappop(min_heap)
            if d > dist[cur]:
                continue
            for nxt, weight in graph[cur]:
                if dist[nxt] > dist[cur] + weight:
                    dist[nxt] = dist[cur] + weight
                    heappush(min_heap, (dist[nxt], nxt))
        return dist

    distances = dijkstra(s)
    return distances[t] if distances[t] != float('inf') else -1
