    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    queue = deque([(s, 0)])
    visited = [False] * n
    distances = [sys.maxsize] * n
    distances[s] = 0
    visited[s] = True

    while queue:
        current, dist = queue.popleft()
