def solve(n, edges):
    from collections import defaultdict

    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    visited = set()

    def dfs(node):
        if node in visited:
            return 0
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)
        return 1

    components = 0
    for node in range(n):
        if node not in visited:
            components += dfs(node)

    return components
