def solve(n, edges):
    def find(x):
        if parent[x] < 0:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        x_set = find(x)
        y_set = find(y)
        if x_set != y_set:
            if -parent[x_set] > -parent[y_set]:
                x_set, y_set = y_set, x_set
            parent[x_set] += parent[y_set]
            parent[y_set] = x_set

    parent = [-1] * n
    for u, v in edges:
        union(u, v)

    return sum(1 for p in parent if p < 0)
