def solve(nums, target):
    def binary_search(lst, target, find_first):
        lo, hi = 0, len(lst) - 1
        idx = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if lst[mid] < target:
                lo = mid + 1
            elif lst[mid] > target:
                hi = mid - 1
            else:
                idx = mid
                if find_first:
                    hi = mid - 1
                else:
                    lo = mid + 1
        return idx

    first = binary_search(nums, target, True)
    last = binary_search(nums, target, False)
    return [first, last]
