        low, high = 0, len(arr) - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] < x:
                low = mid + 1
            elif arr[mid] > x:
                high = mid - 1
            else:
                result = mid
                if left:
                    high = mid - 1
                else:
                    low = mid + 1
        return result

    first = binary_search(nums, target, left=True)
    last = binary_search(nums, target, left=False)

    if first == -1 or last == -1 or first > last:
        return [-1, -1]
    return [first, last]
