        for dr, dc in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            nr, nc = r + dr, c + dc
            if valid(nr, nc):
                yield nr, nc

    def bfs(frontier, visited, target):
        while frontier:
            r, c, path = frontier.popleft()
            if (r, c) == target:
                return path + [(r, c)]
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    frontier.append((nr, nc, path + [(r, c)]))
        return None

    frontiers = {start: [(start, [])], goal: [(goal, [])]}
    visited = set(start + goal)
    while any(frontiers.values()):
        to_merge = set()
        merge = set()
        for position in frontiers:
            frontier, path = frontiers[position]
            if position in visited:
                merged_path = bfs(deque(frontier), set(frontiers[goal][0][1]), position)
                if merged_path:
                    return merged_path
                merge.add(position)
            else:
                visited.add(position)
                for nr, nc in neighbors(position[0], position[1]):
                    if (nr, nc) not in visited:
                        to_merge.add((nr, nc))
                        frontiers[(nr, nc)] = [(nr, nc, path + [(position)])] if (nr, nc) not in frontiers else frontiers[(nr, nc)] + [(nr, nc, path + [(position)])]
        to_merge = to_merge - merge
        frontiers = {pos: paths for pos, paths in frontiers.items() if pos in to_merge}
    return []
