def expand(grid, frontier):
    new_frontier = deque()
    while frontier:
        pos = frontier.popleft()
        for dx, dy in DIRS:
            x, y = pos[0] + dx, pos[1] + dy
            if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.':
                if grid[x][y] == 'G':
                    return (pos, (x, y))
                grid[x][y] = grid[pos[0]][pos[1]]
                new_frontier.append((x, y))
    return (None, None)

def bidirectional_bfs(grid, start, goal):
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    grid[start[0]][start[1]] = 'S'
    grid[goal[0]][goal[1]] = 'G'
    front1, front2 = deque([(start, 'S')]), deque([(goal, 'G')])
    while front1 and front2:
        if len(front1) <= len(front2):
            node, char = expand(grid, front1)
            if node and grid[node[0]][node[1]] == char:
                path1, path2 = [node], [node]
                while path1[-1] != start:
                    x, y = path1[-1]
                    for dx, dy in DIRS:
                        nx, ny = x - dx, y - dy
                        if grid[nx][ny] == path1[-2] and (nx, ny) in front1:
                            path1.append((nx, ny))
                            break
                while path2[-1] != goal:
                    x, y = path2[-1]
                    for dx, dy in DIRS:
                        nx, ny = x - dx, y - dy
                        if grid[nx][ny] == path2[-2] and (nx, ny) in front2:
                            path2.append((nx, ny))
                            break
                return path2[::-1] + path1[1:-1]
            if node:
                front1 = deque([node] + list(front1))
        else:
            node, char = expand(grid, front2)
            if node and grid[node[0]][node[1]] == char:
                path1, path2 = [node], [node]
                while path1[-1] != start:
                    x, y = path1[-1]
                    for dx, dy in DIRS:
                        nx, ny = x - dx, y - dy
                        if grid[nx][ny] == path1[-2] and (nx, ny) in front1:
