    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def in_bounds(row, col):
        return 0 <= row < rows and 0 <= col < cols

    def bfs(start, visited, reverse):
        queue = deque([start])
        next_level = deque()
        while queue:
            row, col = queue.popleft()
            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if in_bounds(new_row, new_col) and grid[new_row][new_col] == '.' and (new_row, new_col) not in visited:
                    visited.add((new_row, new_col))
                    if not reverse:
                        next_level.append((new_row, new_col))
                    else:
                        next_level.appendleft((new_row, new_col))
                    if (new_row, new_col) in goal_set:
                        return True
        return False

    start_set, goal_set = {start}, {goal}
    visited_start, visited_goal = set(), set()

    while start_set and goal_set:
        if len(start_set) > len(goal_set):
            start_set, goal_set = goal_set, start_set
            visited_start, visited_goal = visited_goal, visited_start
            bfs(start_set, visited_start, True)
            bfs(goal_set, visited_goal, False)
        else:
            bfs(start_set, visited_start, False)
            if goal in visited_start:
                break
            bfs(goal_set, visited_goal, True)
            if start in visited_goal:
                break

    if goal in visited_start:
        path = []
        cell = goal
        while cell != start:
            path.append(cell)
            for dr, dc in directions:
                new_row, new_col = cell[0] + dr, cell[1] + dc
                if (new_row, new_col) in visited_start and (new_row, new_col) != start:
                    cell = (new_row, new_col)
                    break
        path.append(start)
