        visited_start = set([start])
        visited_goal = set([goal])
        frontier_start = deque([[start]])
        frontier_goal = deque([[goal]])

        while frontier_start and frontier_goal:
            if frontier_start[0][-1] in visited_goal:
                return frontier_start[0]
            if frontier_goal[0][-1] in visited_start:
                return frontier_goal[0]

            if len(frontier_start) <= len(frontier_goal):
