                for node in neighbors(path[-1]):
                    if node not in visited_start and valid(node):
                        visited_start.add(node)
                        frontier_start.append(path + [node])
            else:
                path = frontier_goal.popleft()
                for node in neighbors(path[-1]):
                    if node not in visited_goal and valid(node):
                        visited_goal.add(node)
                        frontier_goal.append(path + [node])

