    start, goal = (start[0], start[1]), (goal[0], goal[1])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal and grid[start[0]][start[1]] != '#':
        return [start]

    def get_neighbors(node):
        r, c = node
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
                yield (nr, nc)

    def bfs(starts):
        visited = set(starts)
        frontier = deque([(node, [node]) for node in starts])
        while frontier:
            node, path = frontier.popleft()
            for next_node in get_neighbors(node):
                if next_node == goal:
                    return path + [next_node]
                if next_node not in visited:
                    visited.add(next_node)
                    frontier.append((next_node, path + [next_node]))
        return []

    forward_frontier, backward_frontier = bfs([start]), bfs([goal])
    while forward_frontier and backward_frontier:
        if forward_frontier[0][0] == backward_frontier[0][0]:
            return forward_frontier[0][1] + backward_frontier[0][1][::-1][1:]
        new_frontier = []
        for node, path in forward_frontier:
            for next_node in get_neighbors(node):
                if next_node == backward_frontier[0][0]:
                    return path + [next_node] + backward_frontier[0][1][::-1][1:]
                if next_node not in set(ab for a, b in backward_frontier):
                    new_frontier.append((next_node, path + [next_node]))
        forward_frontier = bfs(new_frontier)
        if forward_frontier and forward_frontier[0][0] == backward_frontier[0][0]:
            return forward_frontier[0][1] + backward_frontier[0][1][::-1][1:]
    return []
