from collections import deque

class IDDFS:
    def __init__(self, grid, start, goal):
        self.grid = grid
        self.start = start
        self.goal = goal
        self.rows = len(grid)
        self.cols = len(grid[0])
        self.directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def is_valid(self, x, y):
        return 0 <= x < self.rows and 0 <= y < self.cols and self.grid[x][y] == '.'

    def get_path(self, state):
        path = []
        while state:
            path.append(state)
            state = self.path[state]
        return path[::-1]

    def find_path(self, depth):
        stack = deque([(self.start, (None, None))])
        self.path = {}
        visited = set([self.start])

        while stack:
            current, parent = stack.pop()
            if current == self.goal:
                self.path[self.goal] = parent
                return True
            if len(self.path) > depth:
                continue
            for dx, dy in self.directions:
                nx, ny = current[0] + dx, current[1] + dy
                if self.is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    self.path[(nx, ny)] = current
                    stack.append(((nx, ny), current))
        return False

def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    max_depth = min(len(grid), len(grid[0]))
    iddfs = IDDFS(grid, start, goal)

    for depth in range(max_depth + 1):
        iddfs.path.clear()
        if iddfs.find_path(depth):
            return iddfs.get_path((None, None))

    return []
