from collections import namedtuple

Node = namedtuple('Node', ['f', 'g', 'h', 'row', 'col', 'parent'])

def heuristic(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def solve(grid, start, goal):
    def neighbors(r, c):
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield nr, nc

    closed_set = set()
    open_set = []
    heappush(open_set, Node(heuristic(start, goal), 0, heuristic(start, goal), start[0], start[1], None))

    while open_set:
        current = heappop(open_set)
        if current.row == goal[0] and current.col == goal[1]:
            path = []
            while current:
                path.append((current.row, current.col))
                current = current.parent
            return path[::-1] if path else []
        closed_set.add((current.row, current.col))

        for neighbor in neighbors(current.row, current.col):
            if neighbor in closed_set:
                continue
            tentative_g = current.g + 1
            if any(n.row == neighbor[0] and n.col == neighbor[1] and n.g >= tentative_g for n in open_set):
                continue
            heappush(open_set, Node(current.h + heuristic(neighbor, goal), tentative_g, current.h, neighbor[0], neighbor[1], current))
    return []
