    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = set()
    heap = [(0, start)]

    while heap:
        weight, (row, col) = heappop(heap)
        if (row, col) in visited:
            continue
        visited.add((row, col))

        if (row, col) == goal:
            path = [(row, col)]
            current = (row, col)
            while current != start:
                for dr, dc in directions:
                    nr, nc = current[0] + dr, current[1] + dc
                    if (nr, nc) in visited and 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                        path.append((nr, nc))
                        current = (nr, nc)
                        break
            return path[::-1]

        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                heappush(heap, (weight + 1, (nr, nc)))

    return []
