from collections import deque

def solve(n, edges, s, t):
    import heapq

    def bellman_ford():
        dist = [float('inf')] * n
        dist[s] = 0
        for _ in range(n - 1):
            update = False
            for u, v, w in edges:
                if dist[u] != float('inf') and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    update = True
            if not update:
                break
        else:
            for u, v, w in edges:
                if dist[u] != float('inf') and dist[u] + w < dist[v]:
                    return -1
        return dist[t] if dist[t] != float('inf') else -1

    def spfa():
        dist = [float('inf')] * n
        dist[s] = 0
        queue = deque([s])
        visited = [False] * n
        visited[s] = True

        while queue:
            u = queue.popleft()
            visited[u] = False
            for v, w in adj_list[u]:
                if dist[u] != float('inf') and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    if not visited[v]:
                        queue.append(v)
                        visited[v] = True
            if not visited[u] and u == t:
                return -1
        return dist[t] if dist[t] != float('inf') else -1

    adj_list = [[] for _ in range(n)]
    for u, v, w in edges:
        adj_list[u].append((v, w))

    return spfa() if n > 50 else bellman_ford()
