def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    def bidirectional_dijkstra():
        dist = [[float('inf')] * n for _ in range(2)]
        dist[0][s], dist[1][t] = 0, 0
        seen = [[False] * n for _ in range(2)]
        min_heap = [(0, s, 0), (0, t, 1)]

        while min_heap:
            d, u, side = heappop(min_heap)
            if seen[side][u]:
                continue
            seen[side][u] = True
            for v, w in graph[u]:
                if d + w < dist[side][v]:
                    dist[side][v] = d + w
                    if not seen[1-side][v]:
                        heappush(min_heap, (dist[1-side][v], v, 1-side))

        return min(dist[0][u] + dist[1][u] for u in range(n) if seen[0][u] and seen[1][u] and u != t) if any(seen[0]) and any(seen[1]) else -1

    return bidirectional_dijkstra()
