from heapq import heappush, heappop
from collections import defaultdict

def bidirectional_dijkstra(n, edges, s, t):
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heappop(heap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heappush(heap, (dist[v], v))
        return dist[end]

    def bdijsktra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(-0, start)]  # negate to simulate max heap for min distance
        while heap:
            d, u = heappop(heap)
            if -d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > -d + w:
                    dist[v] = -d + w
                    heappush(heap, (-(dist[v], v)))
        return -dist[end]

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    front = dijkstra(s, n-1)
    back = bdijsktra(t, 0)
    if front == float('inf') or back == float('inf'):
        return -1
    return front + back
