from heapq import heappush, heappop

def solve(n, edges, s, t):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    def bidirectional_dijkstra():
        forward_queue = [(0, s)]
        backward_queue = [(0, t)]
        forward_distances = {s: 0}
        backward_distances = {t: 0}
        found = False

        while forward_queue and backward_queue and not found:
            if len(forward_queue) <= len(backward_queue):
                current_distance, u = heappop(forward_queue)
                if u in backward_distances:
                    found = True
                    meeting_point = u
                    break
                for v, w in graph[u]:
                    if v not in forward_distances or current_distance + w < forward_distances[v]:
                        forward_distances[v] = current_distance + w
                        heappush(forward_queue, (forward_distances[v], v))
            else:
                current_distance, u = heappop(backward_queue)
                if u in forward_distances:
                    found = True
                    meeting_point = u
                    break
                for v, w in graph[u]:
                    if v not in backward_distances or current_distance + w < backward_distances[v]:
                        backward_distances[v] = current_distance + w
                        heappush(backward_queue, (backward_distances[v], v))

        if not found:
            return -1
        return forward_distances[meeting_point] + backward_distances[meeting_point]

    return bidirectional_dijkstra()
