    queue = deque([(s, 0)])
    visited = {s}

    while queue:
        curr, cost = queue.popleft()
        for next_node, weight in graph[curr]:
            if next_node not in visited:
                new_cost = cost + weight
                if next_node == t:
                    return new_cost
                queue.append((next_node, new_cost))
                visited.add(next_node)

    return -1
