def solve(nums, k):
    if not 1 <= k <= len(nums):
        raise ValueError("k is out of bounds")

    import random
    import heapq

    def nth_element(arr, n, left, right):
        if left == right:
            return arr[left]
        pivot_idx = random.randint(left, right)
        pivot_idx = partition(arr, left, right, pivot_idx)
        if n == pivot_idx:
            return arr[n]
        elif n < pivot_idx:
            return nth_element(arr, n, left, pivot_idx - 1)
        else:
            return nth_element(arr, n, pivot_idx + 1, right)

    def partition(arr, left, right, pivot_idx):
        pivot = arr[pivot_idx]
        arr[pivot_idx], arr[right] = arr[right], arr[pivot_idx]
        store_idx = left
        for i in range(left, right):
            if arr[i] < pivot:
                arr[i], arr[store_idx] = arr[store_idx], arr[i]
                store_idx += 1
        arr[store_idx], arr[right] = arr[right], arr[store_idx]
        return store_idx

    return nth_element(nums, k - 1, 0, len(nums) - 1)
