    if len(nums) == 1:
        return nums[0]
    pivot = choose_pivot(nums)
    less, equal, greater = partition(nums, pivot)
    k -= len(equal)
    if k <= len(less):
        return solve(less, k)
    elif k > len(less) + len(equal):
        return solve(greater, k - len(less) - len(equal))
    else:
        return pivot
