def rolling_hash(text, pattern):
    from collections import defaultdict
    from functools import reduce
    from operator import add
    from string import ascii_lowercase

    prime = 31
    alphabet_size = len(ascii_lowercase)
    pattern_hash = reduce(add, (ascii_lowercase.index(c) * (prime ** i) for i, c in enumerate(pattern)), 0)
    text_hash = reduce(add, (ascii_lowercase.index(c) * (prime ** i) for i, c in enumerate(text[:len(pattern)])), 0)
    if text_hash == pattern_hash and text[:len(pattern)] == pattern:
        return 0
    base = prime ** (len(pattern) - 1)
    for i in range(len(pattern), len(text)):
        text_hash = text_hash - (ascii_lowercase.index(text[i - len(pattern)]) * base) * prime + (ascii_lowercase.index(text[i]))
        if text_hash == pattern_hash and text[i - len(pattern) + 1:i + 1] == pattern:
            return i - len(pattern) + 1
    return -1

def solve(haystack, needle):
