def rolling_hash(text, window_size, base=256, prime=1000000007):
    if len(text) < window_size:
        return -1

    hash_value = 0
    base_l = pow(base, window_size - 1, prime)

    for i in range(len(text)):
        if i < window_size:
            hash_value = (hash_value * base + ord(text[i])) % prime
        else:
            hash_value = (hash_value - ord(text[i - window_size]) * base_l) % prime
            hash_value = (hash_value * base + ord(text[i])) % prime

    return hash_value

