def rolling_hash(s, length, base=256, prime=1000000007):
    hash_value = 0
    for i, char in enumerate(s):
        hash_value = (hash_value * base + ord(char)) % prime
        if i >= length - 1:
            yield hash_value
            hash_value = (hash_value - ord(s[i - length + 1]) * (base ** (length - 1))) % prime
            if hash_value < 0:
                hash_value += prime

def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1
    needle_hash = sum(ord(char) for char in needle)
    haystack_hash = next(rolling_hash(haystack, len(needle)))
    if needle_hash == haystack_hash:
        return 0
    for i in range(len(haystack) - len(needle)):
        haystack_hash = (haystack_hash - ord(haystack[i]) + ord(haystack[i + len(needle)])) % 1000000007
        if haystack_hash < 0:
            haystack_hash += 1000000007
        if haystack_hash == needle_hash:
            return i + 1
    return -1
