def solve(n, edges):
    from collections import defaultdict

    def find(root):
        if root not in parent:
            parent[root] = root
        if root != parent[root]:
            parent[root] = find(parent[root])
        return parent[root]

    def union(a, b):
        pa, pb = find(a), find(b)
        if pa != pb:
            parent[pb] = pa

    parent = {}
    for u, v in edges:
        union(u, v)

    components = set(find(i) for i in range(n))
    return len(components)
```

