def solve(n, edges):
    from collections import defaultdict

    # Create adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    visited = [False] * n
    components = 0

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            for neighbor in adj_list[node]:
                dfs(neighbor)

    for node in range(n):
        if not visited[node]:
            dfs(node)
            components += 1

