def solve(n, edges):
    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    parent = list(range(n))
    rank = [0] * n
    for u, v in edges:
        union(parent, rank, u, v)

    components = set()
    for i in range(n):
        components.add(find(parent, i))

    return len(components)
