    from collections import defaultdict

    # Build the graph as an adjacency list
    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    def find_components(node, visited):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            find_components(neighbor, visited)
        return

    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            find_components(i, visited)
            components += 1

    return components
```

