def aho_corasick_z(s, subs):
    z = [0] * len(s)
    z[0] = len(s)
    i = 1
    j = 0
    while i < len(s):
        if s[i] == s[j]:
            z[i] = j + 1
            i += 1
            j += 1
        elif j > 0:
            j = z[j - 1]
        else:
            z[i] = 0
            i += 1
    return z
