def solve(nums, target):
    def binary_search(nums, target, find_first):
        lo, hi = 0, len(nums) - 1
        idx = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:
                idx = mid
                if find_first:
                    hi = mid - 1
                else:
                    lo = mid + 1
            elif nums[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return idx

    first = binary_search(nums, target, True)
    last = binary_search(nums, target, False)
    return [first, last]
