            else:
                right = mid - 1
        return first

    def binary_search_last(nums, target):
        left, right = 0, len(nums) - 1
        last = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                last = mid
                left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return last

    first = binary_search_first(nums, target)
    last = binary_search_last(nums, target)
    return [first, last]
