def solve(nums, target):
    def binarysearch(nums, target, find_first):
        left, right = 0, len(nums) - 1
        index = -1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                index = mid
                if find_first:
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return index

    first = binarysearch(nums, target, True)
    last = binarysearch(nums, target, False)
    return [first, last]
